/** MIT; own dimensional original U012 reconstruction,no imported native geometry. */
import * as THREE from 'three';
import {Port,materials} from '../../core/index.js';
import {roundedRect} from '../../core/geometry.js';
import {mesh,FACE,portQuaternion} from '../../modeling/parts.js';
import {solid,circleHole,frontContour,openRing,ringShape,relief} from './geometry.js';
import {spec} from './dimensions.js';
import {addStickers} from './stickers.js';
const PI=Math.PI;
function board(parent){const green=materials.plastic(0x294437,{roughness:.9}),metal=materials.metal(0xb3b5a6,{roughness:.46}),black=materials.plastic(0x20231e,{roughness:.79}),tan=materials.plastic(0xb7a078,{roughness:.86}),s=new THREE.Shape();s.moveTo(-10.3,-11.8);s.lineTo(-8.3,-13.8);s.lineTo(8.3,-13.8);s.lineTo(10.3,-11.8);s.lineTo(10.3,-7.55);s.lineTo(8,-7.55);s.absarc(8,-4,3.55,-Math.PI/2,-Math.PI*1.5,true);s.lineTo(10.3,-.45);s.lineTo(10.3,11.8);s.lineTo(8.3,13.8);s.lineTo(-8.3,13.8);s.lineTo(-10.3,11.8);s.lineTo(-10.3,-.45);s.lineTo(-8,-.45);s.absarc(-8,-4,3.55,Math.PI/2,-Math.PI/2,true);s.lineTo(-10.3,-7.55);s.closePath();circleHole(s,0,-4,1.9);const groveHoles=[-3,-1,1,3].map(x=>[x,-9.65]),terminalHoles=spec.terminal.pinX.map(x=>[x,5.8]);for(const[x,y]of[...groveHoles,...terminalHoles])circleHole(s,x,y,.45);const pcb=solid(parent,s,.8,[0,0,-.5],green,'DAC inferred physical PCB with actual mounting/lead drills');const lands=[],barrels=[];for(const[x,y]of[...groveHoles,...terminalHoles]){const ann=new THREE.Shape();circleHole(ann,0,0,.43);ann.absarc(0,0,.72,0,PI*2,false);for(const z of[-.55,.3])lands.push(solid(parent,ann,.05,[x,y,z],metal,'DAC retained annular solder land'));const tube=new THREE.Shape();tube.absarc(0,0,.45,0,PI*2,false);circleHole(tube,0,0,.3);barrels.push(solid(parent,tube,.8,[x,y,-.5],metal,'DAC plated lead retention barrel'));}
 const packages={},leads=[],passives=[];for(const[id,x,y,pins]of[['MCP4725',-3,5,6],['LM321MFX',3,4,5]]){packages[id]=mesh(parent,new THREE.BoxGeometry(2.9,1.65,.95),black,[x,y,.775],'DAC own '+id+' fixed package');for(let i=0;i<pins;i++)leads.push(mesh(parent,new THREE.BoxGeometry(.35,.65,.17),metal,[x+((i%3)-1)*.95,y+(i<3?-1:1)*.9,.385],'DAC '+id+' fixed solder terminal'));}for(const[id,x,y,isCap]of[['R1',-4,9,0],['R2',0,9,0],['C1',-6,-.5,1],['C2',0,1,1],['C3',6,2,1]]){passives.push(mesh(parent,new THREE.BoxGeometry(1.6,.8,isCap?.6:.4),isCap?tan:black,[x,y,isCap?.6:.5],'DAC '+id+' fixed passive'));for(const dx of[-.65,.65])leads.push(mesh(parent,new THREE.BoxGeometry(.3,.8,.17),metal,[x+dx,y,.385],'DAC '+id+' solder termination'));}return{pcb,lands,barrels,packages,leads,passives};}
function grove(host,parent){const frame=new THREE.Group();frame.name='DAC burgundy HY2.0 receiving assembly';frame.position.fromArray(spec.grove.position);frame.quaternion.copy(FACE.bottom);parent.add(frame);const plastic=materials.plastic(spec.grove.color,{roughness:.7}),metal=materials.metal(0xb4b4a2,{roughness:.43}),box=(s,p,n,m=plastic)=>mesh(frame,new THREE.BoxGeometry(...s),m,p,'DAC Grove '+n),walls=[];for(const sign of[-1,1]){walls.push(box([.65,5.2,6.7],[sign*4.675,0,-3.35],'receiving side wall'));walls.push(box([.65,.45,1.6],[sign*3.8,2.375,-2.4],'actual latch shoulder'));}const floor=box([8.7,.65,6.7],[0,-2.275,-3.35],'receiving floor'),back=box([8.7,4.55,.65],[0,.325,-6.375],'deep insertion stop'),bridge=box([4.8,.45,2],[0,2.375,-5.2],'locking bridge'),contacts=[],returns=[],tails=[];for(let i=0;i<4;i++){const x=(i-1.5)*2;contacts.push(box([.42,.42,4.7],[x,-.2,-3.7],'contact '+(i+1),metal));returns.push(box([.42,1.8,.42],[x,-.9,-6.35],'bent return '+(i+1),metal));tails.push(box([.42,1,.42],[x,-1.4,-6.35],'soldered tail '+(i+1),metal));}const port=host.add(new Port({id:'grove',label:'PORT.A physical4P',connector:'grove',position:spec.grove.position,quaternion:portQuaternion('bottom'),hitSize:[10,1,5.2],pins:[{n:1,name:'GND',color:'black'},{n:2,name:'5V',color:'red'},{n:3,name:'SDA',color:'yellow'},{n:4,name:'SCL',color:'white'}],meta:{role:'visual-connector',scope:'Physical four-contact attachment and documentary names only;no conversion,I2C,voltage or firmware'}}),parent);return{frame,walls,floor,back,bridge,contacts,returns,tails,port};}
function terminal(host,parent){const frame=new THREE.Group();frame.position.fromArray(spec.terminal.position);frame.name='DAC fixed2P receiving socket';parent.add(frame);const orange=materials.plastic(0xd77c38,{roughness:.73}),metal=materials.metal(0xb2b2a2,{roughness:.44}),box=(s,p,n,m=orange)=>mesh(frame,new THREE.BoxGeometry(...s),m,p,'DAC fixed2P '+n),walls=[];for(const x of[-4.125,4.125])walls.push(box([.25,.85,3.95],[x,-.425,-.2],'receiving partition'));const floor=box([8.5,.85,.35],[0,-.425,-2.35],'receiving floor'),back=box([8.5,.25,4.3],[0,-.975,-.2],'deep insertion stop'),pins=[],returns=[],tails=[];for(const x of spec.terminal.pinX){pins.push(box([.45,.65,.45],[x,-.4,-.55],'mating pin',metal));returns.push(box([.45,.45,3.6],[x,-.6,-2.0],'PCB return conductor',metal));tails.push(box([.45,.45,.8],[x,-.6,-4.2],'throughPCB solder tail',metal));}const port=host.add(new Port({id:'terminal',label:'Original U012 removable2P',connector:spec.terminal.connector,position:spec.terminal.position,hitSize:[8.65,1,4.3],meta:{role:'visual-connector',scope:'Actual mechanical plug removal only;no voltage,EEPROM,waveform or electrical state'}}),parent);return{frame,walls,floor,back,pins,returns,tails,port};}
export function buildDAC(host){const frame=new THREE.Group();frame.name='DAC complete own-dimensional assembly';host.body.add(frame);const white=materials.plastic(0xecece6,{roughness:.79}),metal=materials.metal(0xa9ada4,{roughness:.48});const rearShape=roundedRect(24,32,4),frontShape=frontContour();for(const[x,y]of spec.mountingHolesMm){circleHole(rearShape,x,y,2.5);circleHole(frontShape,x,y,2.5);}circleHole(rearShape,0,-4,1.5);const rear=solid(frame,rearShape,.8,[0,0,-3.8],white,'DAC closed rear shell with two true5mm bores');const front=solid(frame,frontShape,1,[0,0,3],white,'DAC front shell real terminal andGrove edge openings');const rearRim=solid(frame,ringShape(24,32,4,21.6,29.6,2.8),.2,[0,0,-4],white,'DAC rear perimeter rim supporting recessed rear panel');const lowerRing=solid(frame,ringShape(24,32,4,21.6,29.6,2.8),1.8,[0,0,-3],white,'DAC rear perimeter structural wall');const upperRing=solid(frame,openRing(),4.2,[0,0,-1.2],white,'DAC openGrove perimeter wall');const sleeves=[];for(const[x,y]of spec.mountingHolesMm){const s=new THREE.Shape();s.absarc(0,0,3.5,0,PI*2,false);circleHole(s,0,0,2.5);sleeves.push(solid(frame,s,6,[x,y,-3],white,'DAC true mounting bore sleeve'));}const boardParts=board(frame),groveParts=grove(host,frame),terminalParts=terminal(host,frame),supports=[];for(const[x,y]of[[-6,11],[6,11],[-5,-11],[5,-11]])supports.push(mesh(frame,new THREE.BoxGeometry(1.4,1.4,2.5),white,[x,y,-1.75],'DAC PCB support to actual rear shell'));
 const boss=new THREE.Shape();boss.absarc(0,0,2,0,PI*2,false);circleHole(boss,0,0,.75);const screwBoss=solid(frame,boss,5.6,[0,-4,-3],white,'DAC central fixing receiver boss'),shank=mesh(frame,new THREE.CylinderGeometry(.65,.65,6,24).rotateX(PI/2),metal,[0,-4,-.5],'DAC retaining screw shank'),head=mesh(frame,new THREE.CylinderGeometry(1.35,1.35,.45,48).rotateX(PI/2),metal,[0,-4,-3.775],'DAC rear retaining screw head'),hex=mesh(frame,new THREE.CylinderGeometry(.5,.5,.02,6).rotateX(PI/2),materials.plastic(0x30342e),[0,-4,-3.99],'DAC observed hex recess dark floor');
 const rearFilm=mesh(frame,new THREE.BoxGeometry(16,12,.05),materials.plastic(0xeeeae0,{roughness:.91}),[0,7.8,-3.825],'DAC rear real physical label film');rearFilm.userData.role='physical-label-substrate';
 const rearRelief=relief(frame,[[[-4,-1.8],[-4,1.8],[-2,0],[0,1.8],[0,-1.8]],[[4,1.8],[1.4,1.8],[1.4,0],[3.6,0],[4,-.5],[4,-1.3],[3.5,-1.8],[1.2,-1.8]]],{position:[0,-10,-3.86],material:white,width:.14,name:'DAC unpainted rear M5 solid relief'});rearRelief.scale.x=-1;const frontRelief=relief(frame,[[[-2.65,-1.3],[-2.65,1.3],[-1.7,1.3],[-1.15,.8],[-1.15,-.8],[-1.7,-1.3],[-2.65,-1.3]],[[-.65,-1.3],[.1,1.3],[.85,-1.3]],[[-.4,-.45],[.6,-.45]],[[2.8,1.1],[2.3,1.3],[1.7,1.3],[1.3,.75],[1.3,-.75],[1.7,-1.3],[2.3,-1.3],[2.8,-1.1]],[[-1.7,3],[0,4.7],[1.7,3],[-1.7,3]]],{position:[0,.5,4],material:white,width:.14,name:'DAC own unpainted DAC arrow solid relief'});
 host.dacAssembly={frame,shell:{rear,rearRim,front,lowerRing,upperRing,sleeves},board:boardParts,grove:groveParts,terminal:terminalParts,supports,fixing:{screwBoss,shank,head,hex},rearFilm,rearRelief,frontRelief};host.unitStickers=addStickers(host,rearFilm);}
